[
  {
    "statement": "Several methods for controlling sea lice on Atlantic salmon farms have been evaluated.",
    "citations": [
      "738",
      "741",
      "1026"
    ]
  },
  {
    "statement": "Corkwing and goldskinny cleaner wrasse were as effective at controlling lice infestation as chemical treatments.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Rockcook cleaner wrasse were ineffective at preventing lice outbreaks.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Salmon kept in low intensity artificial light or natural lighting had lower numbers of lice compared to salmon under more intense artificial light.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "Lower lice numbers were recorded on Atlantic salmon in cages using a fallowing system.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "Studies did not directly compare the cost-effectiveness of different sea lice control methods.",
    "citations": []
  },
  {
    "statement": "No specific economic analysis or cost data was provided to determine which method for controlling sea lice is most cost-effective.",
    "citations": []
  }
]
